function ft_file(string $rel): bool { return is_file(__DIR__.'/../'.$rel); }
function ft_col(string $t,string $c): bool { global $pdo; try{$q=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?");$q->execute([$t,$c]);return (bool)$q->fetchColumn();}catch(Throwable $e){return false;} }
function ft_table(string $t): bool { global $pdo; try{$q=$pdo->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?");$q->execute([$t]);return (bool)$q->fetchColumn();}catch(Throwable $e){return false;} }
function ft_has(string $file,string $needle): bool { if(!ft_file($file))return false;$s=(string)@file_get_contents(__DIR__.'/../'.$file);return stripos($s,$needle)!==false; }
function ft_mail_config(): array { $p=__DIR__.'/../config/mail.php';if(!is_file($p))return [false,'config/mail.php is missing'];try{$c=require $p;if(!is_array($c))return [false,'mail.php did not return a configuration array'];foreach(['host','port','username','password','from_email'] as $k)if(trim((string)($c[$k]??''))===''||str_contains((string)($c[$k]??''),'YOUR_'))return [false,'Mail configuration field "'.$k.'" is missing or still a placeholder'];return [true,'SMTP configuration is structurally complete'];}catch(Throwable $e){return [false,'Could not load mail configuration: '.$e->getMessage()];} }
function ft_add(array &$r,string $id,string $cat,string $label,bool $ok,string $details,string $fix=''): void { $r[]=['id'=>$id,'category'=>$cat,'label'=>$label,'ok'=>$ok,'details'=>$details,'fix'=>$fix]; }
function functional_tests(): array {
 global $pdo;$r=[];
 try{$v=$pdo->query('SELECT 1')->fetchColumn();ft_add($r,'db_connection','Infrastructure','Database connection',((string)$v==='1'),'MySQL responded successfully.');}catch(Throwable $e){ft_add($r,'db_connection','Infrastructure','Database connection',false,'Database query failed: '.$e->getMessage());return $r;}
 ft_add($r,'php','Infrastructure','PHP runtime',version_compare(PHP_VERSION,'8.1','>='),'Running PHP '.PHP_VERSION.'. Minimum supported runtime is PHP 8.1.');
 ft_add($r,'pdo_mysql','Infrastructure','PDO MySQL driver',extension_loaded('pdo_mysql'),'PDO MySQL '.(extension_loaded('pdo_mysql')?'is loaded':'is missing').'.');
 foreach(['openssl','mbstring','json','filter'] as $x)ft_add($r,'ext_'.$x,'Infrastructure','PHP extension: '.$x,extension_loaded($x),extension_loaded($x)?'Extension is loaded.':'Required application extension is missing.');
 ft_add($r,'db_write','Infrastructure','Database transaction/write capability',false,'', '');
 try{$pdo->exec('CREATE TEMPORARY TABLE IF NOT EXISTS shadril_functional_test (id INT PRIMARY KEY,value VARCHAR(20))');$pdo->exec("INSERT INTO shadril_functional_test(id,value) VALUES(1,'OK')");$v=$pdo->query('SELECT value FROM shadril_functional_test WHERE id=1')->fetchColumn();$pdo->exec('DROP TEMPORARY TABLE shadril_functional_test');$r[count($r)-1]=['id'=>'db_write','category'=>'Infrastructure','label'=>'Database transaction/write capability','ok'=>$v==='OK','details'=>$v==='OK'?'Temporary write/read test succeeded; application database writes are available.':'Temporary write/read test returned an unexpected result.','fix'=>''];}catch(Throwable $e){$r[count($r)-1]=['id'=>'db_write','category'=>'Infrastructure','label'=>'Database transaction/write capability','ok'=>false,'details'=>'Temporary database write/read test failed: '.$e->getMessage(),'fix'=>'repair_schema'];}
 foreach([['database.php','Database configuration'],['mail.php','Mail configuration']] as $x)ft_add($r,'cfg_'.$x[0],'Configuration',$x[1],ft_file('config/'.$x[0]),ft_file('config/'.$x[0])?'Configuration file is present.':'Configuration file is missing.','');
 [$mok,$md]=ft_mail_config();ft_add($r,'smtp','Email & OTP','SMTP configuration',$mok,$md,'');
 ft_add($r,'otp_table','Authentication','Customer OTP/reset table',ft_table('password_reset_otps'),ft_table('password_reset_otps')?'password_reset_otps exists.':'password_reset_otps is missing; customer forgot-password/OTP cannot work correctly.','repair_schema');
 foreach([['customers','Customer account table'],['users','Management account table'],['admin_password_resets','Admin recovery table']] as $x)ft_add($r,'tbl_'.$x[0],'Authentication',$x[1],ft_table($x[0]),ft_table($x[0])?$x[0].' exists.':$x[0].' is missing.','repair_schema');
 foreach([['customer-register','auth/register.php','Registration'],['customer-login','auth/customer-login.php','Customer login'],['customer-forgot','auth/forgot-password.php','Customer forgot password'],['otp','auth/verify-otp.php','OTP verification'],['customer-reset','auth/reset-password.php','Customer password reset'],['logout','auth/logout.php','Logout'],['admin-login','auth/login.php','Admin login'],['admin-forgot','auth/admin-forgot-password.php','Admin forgot password'],['admin-reset','auth/admin-reset-password.php','Admin password reset'],['admin-password','admin/password.php','Admin change password']] as $x)ft_add($r,$x[0],'Authentication',$x[2],ft_file($x[1]),ft_file($x[1])?$x[1].' exists.':$x[1].' is missing.','');
 ft_add($r,'otp_resend','Authentication','OTP resend functionality',ft_has('auth/verify-otp.php',"action==='resend")&&ft_has('auth/verify-otp.php','send_customer_otp_html'),ft_has('auth/verify-otp.php',"action==='resend")?'Resend OTP action is implemented with a cooldown and email sender.':'Resend OTP action is missing or not wired to the email sender.','');
 ft_add($r,'password_hash','Authentication','Password hashing API',function_exists('password_hash')&&function_exists('password_verify'),'PHP password_hash/password_verify APIs are available.');
 ft_add($r,'csrf','Security','CSRF protection',function_exists('csrf_field')&&function_exists('check_csrf'),'Application bootstrap exposes CSRF field and validation functions.','');
 ft_add($r,'session','Security','Secure session controls',ini_get('session.cookie_httponly')==='1',ini_get('session.cookie_httponly')==='1'?'HttpOnly session cookies are enabled.':'HttpOnly session cookies are not enabled for the current PHP runtime.','secure_sessions');
 foreach([['products','Catalogue'],['categories','Categories'],['orders','Orders'],['order_items','Order items'],['transactions','Stock transactions'],['support_tickets','Support tickets'],['support_replies','Support replies'],['customer_private_messages','Private customer chat'],['product_reviews','Product reviews'],['customer_preferences','Customer preferences'],['store_config','Store configuration'],['system_health_log','Health log'],['security_events','Security events'],['system_alerts','System alerts']] as $x)ft_add($r,'tblbiz_'.$x[0],'Application data',$x[1],ft_table($x[0]),ft_table($x[0])?$x[0].' is available.':$x[0].' is missing.','repair_schema');
 foreach([['shop/cart.php','Cart'],['shop/checkout.php','Checkout'],['shop/buy-now.php','Buy now'],['shop/product.php','Product details'],['shop/live-stock.php','Live stock'],['admin/stock.php','Admin stock control'],['admin/orders.php','Admin orders'],['admin/support.php','Admin support'],['customer/orders.php','Customer orders'],['customer/support.php','Customer support'],['customer/messages.php','Customer private messages']] as $x)ft_add($r,'page_'.md5($x[0]),'Application flows',$x[1],ft_file($x[0]),ft_file($x[0])?$x[0].' exists.':$x[0].' is missing.','');
 foreach([['products','cost_price'],['transactions','unit_cost'],['order_items','unit_cost'],['orders','discount_amount'],['orders','tracking_location'],['orders','tracking_eta']] as $x)ft_add($r,'col_'.$x[0].'_'.$x[1],'Database schema','Column '.$x[0].'.'.$x[1],ft_col($x[0],$x[1]),ft_col($x[0],$x[1])?'Column exists.':'Column is missing.','repair_schema');
 try{$n=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE quantity_in_stock<0')->fetchColumn();ft_add($r,'negative_stock','Data integrity','Negative stock balances',$n===0,$n===0?'No negative balances found.':$n.' product(s) have negative stock.','fix_negative_stock');}catch(Throwable $e){ft_add($r,'negative_stock','Data integrity','Negative stock balances',false,$e->getMessage(),'fix_negative_stock');}
 try{$n=(int)$pdo->query('SELECT COUNT(*) FROM order_items oi LEFT JOIN orders o ON o.order_id=oi.order_id WHERE o.order_id IS NULL')->fetchColumn();ft_add($r,'orphan_items','Data integrity','Orphan order items',$n===0,$n===0?'No orphan order items found.':$n.' orphan order item(s) found.','');}catch(Throwable $e){ft_add($r,'orphan_items','Data integrity','Orphan order items',false,$e->getMessage(),'');}
 try{$n=(int)$pdo->query("SELECT COUNT(*) FROM orders o LEFT JOIN (SELECT order_id,SUM(quantity*unit_price) total FROM order_items GROUP BY order_id) x ON x.order_id=o.order_id WHERE ABS((COALESCE(x.total,0)-COALESCE(o.discount_amount,0))-o.total_amount)>0.01 AND o.status<>'CANCELLED'")->fetchColumn();ft_add($r,'order_totals','Data integrity','Order totals match order items',$n===0,$n===0?'All checked order totals match their items and discounts.':$n.' order(s) need recalculation.','repair_totals');}catch(Throwable $e){ft_add($r,'order_totals','Data integrity','Order totals match order items',false,$e->getMessage(),'repair_totals');}
 try{$n=0;if(ft_table('password_reset_otps'))$n+=(int)$pdo->query("SELECT COUNT(*) FROM password_reset_otps WHERE expires_at<NOW() AND verified_at IS NULL")->fetchColumn();if(ft_table('admin_password_resets'))$n+=(int)$pdo->query("SELECT COUNT(*) FROM admin_password_resets WHERE expires_at<NOW() AND used_at IS NULL")->fetchColumn();ft_add($r,'expired_resets','Authentication','Expired reset records',$n===0,$n===0?'No expired unused reset records found.':$n.' expired reset record(s) found.','cleanup_resets');}catch(Throwable $e){ft_add($r,'expired_resets','Authentication','Expired reset records',false,$e->getMessage(),'cleanup_resets');}
 ft_add($r,'assets','Infrastructure','Assets directory',is_dir(__DIR__.'/../assets')&&is_readable(__DIR__.'/../assets'),is_dir(__DIR__.'/../assets')&&is_readable(__DIR__.'/../assets')?'Assets directory is readable.':'Assets directory is missing or unreadable.','');
 ft_add($r,'bootstrap','Application flows','Application bootstrap',ft_file('includes/bootstrap.php')&&ft_has('includes/bootstrap.php','ensure_shadril_schema'),'Bootstrap and schema initializer are present.','repair_schema');
 ft_add($r,'email_sender','Email & OTP','Branded email sender',function_exists('send_store_email'),function_exists('send_store_email')?'SMTP sender function is loaded.':'send_store_email() is unavailable; email notifications/OTP may fail.','');
 ft_add($r,'google','Authentication','Google sign-in configuration',true,'Google OAuth is optional. The application endpoint exists; external OAuth credentials are only required if Google sign-in is enabled.','');
 return $r;
}
function record_alerts(array $tests): void { global $pdo; if(!ft_table('system_alerts'))return; foreach($tests as $t){if($t['ok'])continue;$fp=hash('sha256',$t['id'].'|'.$t['details']);try{$q=$pdo->prepare("INSERT INTO system_alerts(fingerprint,component,severity,message,details,status,last_seen_at) VALUES(?,?,?,?,?,'OPEN',NOW()) ON DUPLICATE KEY UPDATE last_seen_at=NOW(),details=VALUES(details),message=VALUES(message),severity=VALUES(severity),status=IF(status='RESOLVED','OPEN',status)");$sev=in_array($t['category'],['Authentication','Security','Infrastructure'])?'CRITICAL':'HIGH';$q->execute([$fp,$t['category'],$sev,$t['label'].' is failing',$t['details']]);}catch(Throwable $ignore){}}
}
function alerts(): array { global $pdo;try{return $pdo->query("SELECT * FROM system_alerts WHERE status<>'RESOLVED' ORDER BY CASE severity WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 WHEN 'WARNING' THEN 3 ELSE 4 END,last_seen_at DESC LIMIT 50")->fetchAll();}catch(Throwable $e){return [];}}
function run_security_scan(): array { $danger=[];$root=realpath(__DIR__.'/..');$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if($f->isFile()&&preg_match('~\.(php|phtml|phar)$~i',$f->getFilename())){$s=(string)@file_get_contents($f->getPathname());if(preg_match('~(shell_exec\s*\(|passthru\s*\(|system\s*\(|eval\s*\()~i',$s))$danger[]=str_replace($root.'/','',$f->getPathname());}}return $danger;}
if(isset($_GET['heartbeat'])){
 header('Content-Type: application/json; charset=utf-8');
 try{$tests=functional_tests();record_alerts($tests);$fails=array_values(array_filter($tests,fn($x)=>!$x['ok']));echo json_encode(['ok'=>count($fails)===0,'checked'=>count($tests),'failed'=>count($fails),'failures'=>array_map(fn($x)=>['id'=>$x['id'],'label'=>$x['label'],'details'=>$x['details']],$fails)]); }catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'checked'=>0,'failed'=>1,'failures'=>[['id'=>'heartbeat','label'=>'System heartbeat','details'=>$e->getMessage()]]]);}exit;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();$action=(string)($_POST['action']??'');
 if($action==='resolve_alert'&&super_admin()){try{$q=$pdo->prepare("UPDATE system_alerts SET status='RESOLVED',resolved_at=NOW() WHERE alert_id=?");$q->execute([(int)$_POST['alert_id']]);$msg='Alert resolved.';}catch(Throwable $e){$err=$e->getMessage();}}
 elseif(in_array($action,['run_tests','security_scan'],true)){$tests=functional_tests();if($action==='security_scan'){$danger=run_security_scan();if($danger)foreach($danger as $f)$tests[]=['id'=>'security_file_'.md5($f),'category'=>'Security','label'=>'Security scan: '.$f,'ok'=>false,'details'=>'Potentially dangerous PHP execution pattern requires manual review.','fix'=>''];else $tests[]=['id'=>'security_scan','category'=>'Security','label'=>'PHP security-pattern scan','ok'=>true,'details'=>'No common high-risk execution patterns detected.','fix'=>''];}record_alerts($tests);$fails=count(array_filter($tests,fn($x)=>!$x['ok']));health_log('FUNCTIONAL TEST RUN',$fails?'WARNING':'OK','Checked '.count($tests).' tests; failures='.$fails);audit_log('SYSTEM FUNCTIONAL TEST','Checked '.count($tests).' tests; failures='.$fails);$msg='Functional test completed: '.count($tests).' checks, '.$fails.' failure(s).';}
 elseif(super_admin()){
  try{switch($action){case'repair_schema':ensure_shadril_schema();$msg='Database schema checked/repaired safely.';break;case'fix_negative_stock':$n=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE quantity_in_stock<0')->fetchColumn();$pdo->exec("UPDATE products SET quantity_in_stock=0,status='INACTIVE' WHERE quantity_in_stock<0");$msg='Corrected '.$n.' negative stock balance(s).';break;case'repair_totals':$n=0;$q=$pdo->query("SELECT o.order_id,COALESCE(SUM(oi.quantity*oi.unit_price),0) subtotal,COALESCE(o.discount_amount,0) discount,o.total_amount,o.status FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.order_id WHERE o.status<>'CANCELLED' GROUP BY o.order_id,o.discount_amount,o.total_amount,o.status");foreach($q as $x){$total=max(0,(float)$x['subtotal']-(float)$x['discount']);if(abs($total-(float)$x['total_amount'])>.01){$u=$pdo->prepare('UPDATE orders SET total_amount=? WHERE order_id=?');$u->execute([$total,$x['order_id']]);$n++;}}$msg='Corrected '.$n.' order total(s).';break;case'cleanup_resets':$n=0;try{$n+=(int)$pdo->exec('DELETE FROM password_reset_otps WHERE expires_at<NOW()');}catch(Throwable $e){}try{$n+=(int)$pdo->exec('DELETE FROM admin_password_resets WHERE expires_at<NOW()');}catch(Throwable $e){}$msg='Removed '.$n.' expired reset record(s).';break;case'secure_sessions':session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(24));$msg='Current management session regenerated securely.';break;default:throw new RuntimeException('Unknown action.');}health_log('SYSTEM REPAIR','OK',$msg);audit_log('SYSTEM REPAIR',$msg);}catch(Throwable $e){health_log('SYSTEM REPAIR','ERROR',$e->getMessage());$err='Repair failed safely: '.$e->getMessage();}}
 else $err='Only the Super Admin can perform repair actions.';
}
$tests=functional_tests();record_alerts($tests);$fails=array_values(array_filter($tests,fn($x)=>!$x['ok']));$alerts=alerts();$logs=[];try{$logs=$pdo->query('SELECT action,result,details,created_at FROM system_health_log ORDER BY health_id DESC LIMIT 15')->fetchAll();}catch(Throwable $ignore){}
require __DIR__.'/../includes/header.php';
$cats=[];foreach($tests as $t)$cats[$t['category']][]=$t;
