<div class="panel"><h2>What this live monitor can and cannot do</h2><p><strong>It can:</strong> repeatedly test the live PHP/MySQL application, detect missing components, database failures, broken schema, authentication dependencies, stock/data integrity problems, configuration problems and security-pattern warnings, then create an admin alert.</p><p><strong>It cannot:</strong> notify the admin from a completely unreachable server. If the server, DNS, hosting account or network is totally down, there is no PHP process available to send an alert. When this page is open, the browser also detects heartbeat failure and displays an immediate warning; server-side alerts resume automatically when connectivity returns.</p></div>
</section></div>
<script>
(function(){let lastFail=0;async function heartbeat(){try{const r=await fetch('/admin/system.php?heartbeat=1&_='+Date.now(),{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();document.getElementById('heartbeatTime').textContent='Last checked '+new Date().toLocaleTimeString();const s=document.getElementById('liveStatus');if(s)s.textContent=d.failed?'LIVE WARNING: '+d.failed+' system check(s) failing. Review the alerts below.':'Live system check successful — all monitored checks passed.';const c=document.getElementById('alertCount');if(c)c.textContent=d.failed||0;if(d.failed&&!lastFail){lastFail=1;showLiveNotice('SYSTEM ATTENTION REQUIRED','One or more live system checks have failed. Open the System Health page immediately.');}if(!d.failed)lastFail=0;}catch(e){document.getElementById('heartbeatTime').textContent='Heartbeat failed '+new Date().toLocaleTimeString();showLiveNotice('SERVER CONNECTION WARNING','The live system heartbeat could not reach the application. Check hosting, DNS, network and server availability.');}}
function showLiveNotice(title,msg){let n=document.getElementById('liveNotice');if(!n){n=document.createElement('div');n.id='liveNotice';n.className='live-notice';document.body.appendChild(n);}n.innerHTML='<strong>'+title+'</strong><span>'+msg+'</span><button type="button">Dismiss</button>';n.querySelector('button').onclick=()=>n.remove();if('Notification'in window&&Notification.permission==='granted')new Notification(title,{body:msg});}
if('Notification'in window&&Notification.permission==='default'){try{Notification.requestPermission()}catch(e){}}heartbeat();setInterval(heartbeat,30000);})();
</script>
